OM_uint32 spnego_init_reselect_context(OM_uint32 *minor_status,
                                       spnego_gss_ctx_id_t sc,
                                       OM_uint32 acc_negState,
                                       gss_OID supportedMech,
                                       gss_buffer_t *responseToken,
                                       gss_buffer_t *mechListMIC,
                                       OM_uint32 *negState,
                                       send_token_flag *tokflag)
{
    OM_uint32 major_status;
    gss_OID mech_set;
    OM_uint32 tmp_minor;

    if (!sc || !negState || !tokflag) {
        if (minor_status)
            *minor_status = 0;
        return GSS_S_BAD_ARGUMENT;
    }

    /* Delete the current security context */
    gss_delete_sec_context(minor_status, &sc, NULL);

    /* Check if the supported mechanism is in the mechanism set */
    major_status = gss_test_oid_set_member(&tmp_minor, supportedMech, NULL, &mech_set);
    if (major_status != GSS_S_COMPLETE || !mech_set) {
        if (minor_status)
            *minor_status = tmp_minor;
        return GSS_S_BAD_MECH;
    }

    /* Validate the negotiation state */
    if (acc_negState != GSS_C_NO_CONTEXT && acc_negState != GSS_C_ESTABLISHED) {
        if (minor_status)
            *minor_status = 0;
        return GSS_S_BAD_STATE;
    }

    /* Set the internal mechanism */
    sc->internal_mech = supportedMech;

    /* Update the negotiation state */
    *negState = acc_negState;

    /* Set the token flag to send the response token */
    *tokflag = SEND_TOKEN_FLAG;

    /* Clear the response token buffer if provided */
    if (responseToken) {
        responseToken->length = 0;
        responseToken->value = NULL;
    }

    /* Clear the mechListMIC buffer if provided */
    if (mechListMIC) {
        mechListMIC->length = 0;
        mechListMIC->value = NULL;
    }

    if (minor_status)
        *minor_status = 0;
    return GSS_S_COMPLETE;
}

OM_uint32 spnego_gss_context_reslection(OM_uint32 *minor_status,
                                        spnego_gss_ctx_id_t sc,
                                        OM_uint32 acc_negState,
                                        gss_OID supportedMech,
                                        gss_buffer_t *responseToken,
                                        gss_buffer_t *mechListMIC,
                                        OM_uint32 *negState,
                                        send_token_flag *tokflag) {
    OM_uint32 major_status = GSS_S_COMPLETE;
    gss_OID mech_set;
    OM_uint32 tmp_minor;

    *minor_status = 0;

    if (!sc || !supportedMech || !negState || !tokflag) {
        major_status = GSS_S_BAD_ARGUMENT;
        *minor_status = EINVAL;
        return major_status;
    }

    gss_delete_sec_context(&tmp_minor, &sc->internal_context, NULL);

    if (sc->internal_context == NULL) {
        major_status = GSS_S_NO_CONTEXT;
        *minor_status = ENOENT;
        return major_status;
    }

    if (acc_negState != SPNEGO_NEG_STATE_ACCEPTED) {
        *negState = acc_negState;
    }

    if (gss_test_oid_set_member(&tmp_minor, supportedMech, sc->mechSet, NULL) != GSS_S_COMPLETE) {
        major_status = GSS_S_BAD_MECH;
        *minor_status = EINVAL;
        return major_status;
    }

    sc->current_mech = supportedMech;

    if (responseToken != NULL) {
        responseToken->length = 0;
        responseToken->value = NULL;
    }

    if (mechListMIC != NULL) {
        mechListMIC->length = 0;
        mechListMIC->value = NULL;
    }

    *negState = SPNEGO_NEG_STATE_COMPLETE;
    *tokflag = SEND_TOKEN_FLAG_CONTINUE;

    return major_status;
}

OM_uint32 spnego_gss_init_reselect(
    OM_uint32 *minor_status,
    spnego_gss_ctx_id_t sc,
    OM_uint32 acc_negState,
    gss_OID supportedMech,
    gss_buffer_t *responseToken,
    gss_buffer_t *mechListMIC,
    OM_uint32 *negState,
    send_token_flag *tokflag)
{
    OM_uint32 major_status, tmp_negState = 0;
    gss_OID mech_set = GSS_C_NO_OID_SET;
    OM_uint32 tmp_minor_status = 0;
    gss_OID tmp_oid = NULL;
    OM_uint32 count = 0;
    int mech_found = 0;

    /* Delete the current security context if it exists */
    if (sc != NULL) {
        gss_delete_sec_context(&tmp_minor_status, &sc, NULL);
    }

    /* Check if the supported mechanism is in the mechanism set */
    major_status = gss_inquire_cred(&tmp_minor_status, NULL, NULL, &mech_set, NULL);
    if (major_status != GSS_S_COMPLETE) {
        *minor_status = tmp_minor_status;
        return major_status;
    }

    if (mech_set != GSS_C_NO_OID_SET) {
        major_status = gss_test_oid_set_member(&tmp_minor_status, supportedMech, mech_set, &mech_found);
        gss_release_oid_set(&tmp_minor_status, &mech_set);
        if (major_status != GSS_S_COMPLETE) {
            *minor_status = tmp_minor_status;
            return major_status;
        }

        if (!mech_found) {
            *minor_status = 0;
            return GSS_S_BAD_MECH;
        }
    }

    /* Validate the negotiation state */
    if (acc_negState != SPNEGO_NEG_STATE_ACCEPTED) {
        *minor_status = 0;
        return GSS_S_BAD_SIG;
    }

    /* Set internal mechanism and update state */
    sc->internal_mech = supportedMech;

    /* Update the negotiation state */
    *negState = SPNEGO_NEG_STATE_CONTINUE;

    /* Set the token flag */
    *tokflag = SEND_TOKEN_FLAG_RESPONSE;

    *minor_status = 0;
    return GSS_S_COMPLETE;
}

OM_uint32 spnego_init_context_reselection(
    OM_uint32 *minor_status,
    spnego_gss_ctx_id_t sc,
    OM_uint32 acc_negState,
    gss_OID supportedMech,
    gss_buffer_t *responseToken,
    gss_buffer_t *mechListMIC,
    OM_uint32 *negState,
    send_token_flag *tokflag)
{
    OM_uint32 major_status;
    gss_OID_set supported_mech_set;
    gss_OID best_mech;

    /* Delete the current security context */
    (void)gss_delete_sec_context(minor_status, &sc, NULL);

    /* Check if the supported mechanism is in the mechanism set */
    major_status = gss_create_empty_oid_set(minor_status, &supported_mech_set);
    if (major_status != GSS_S_COMPLETE) {
        *minor_status = 0;
        return GSS_S_FAILURE;
    }

    /* Add the supportedMech to the set */
    major_status = gss_add_oid_set_member(minor_status, supportedMech, &supported_mech_set);
    if (major_status != GSS_S_COMPLETE) {
        gss_release_oid_set(minor_status, &supported_mech_set);
        *minor_status = 0;
        return GSS_S_BAD_MECH;
    }

    /* Validate the negotiation state */
    if (acc_negState != GSS_C_NO_CONTEXT && acc_negState != GSS_S_CONTINUE_NEEDED) {
        gss_release_oid_set(minor_status, &supported_mech_set);
        *minor_status = 0;
        return GSS_S_BAD_SIG;
    }

    /* Set the internal mechanism to the supported mechanism */
    sc->mech = *supportedMech;

    /* Update the negotiation state and token flag */
    *negState = GSS_S_CONTINUE_NEEDED;
    *tokflag = SEND_TOKEN_RESPONSE;

    gss_release_oid_set(minor_status, &supported_mech_set);

    *minor_status = 0;
    return GSS_S_CONTINUE_NEEDED;
}

OM_uint32
spnego_init_context_reselection(OM_uint32 *minor_status,
                                spnego_gss_ctx_id_t sc,
                                OM_uint32 acc_negState,
                                gss_OID supportedMech,
                                gss_buffer_t *responseToken,
                                gss_buffer_t *mechListMIC,
                                OM_uint32 *negState,
                                send_token_flag *tokflag)
{
    OM_uint32 major_status;
    OM_uint32 temp_minor;
    gss_OID mech_set;
    OM_uint32 is_supported;

    *minor_status = 0;

    /* Delete the current security context if it exists */
    if (sc != NULL) {
        (void)gss_delete_sec_context(&temp_minor, &sc, NULL);
    }

    /* Check if the supported mechanism is in the mechanism set */
    major_status = gss_test_oid_set_member(&temp_minor, supportedMech, sc->mech_set, &is_supported);
    if (major_status != GSS_S_COMPLETE || !is_supported) {
        *minor_status = temp_minor;
        return GSS_S_BAD_MECH;
    }

    /* Validate the negotiation state */
    if (acc_negState != SPNEGO_NEGSTATE_ACCEPT_COMPLETED) {
        *minor_status = GSS_S_BAD_NAMETYPE;
        return GSS_S_FAILURE;
    }

    /* Set the internal mechanism */
    sc->internal_mech = supportedMech;

    /* Update the negotiation state */
    *negState = SPNEGO_NEGSTATE_INITIATED;

    /* Set the token send flag */
    *tokflag = SEND_TOKEN_FLAG_RESPONSE;

    return GSS_S_COMPLETE;
}
